namespace Facepunch;

// Written by Tools/puddle_textures.py from the puddles' height maps: don't edit it by hand.

/// <summary>
/// Where the water lies in each puddle shape, for the rain's rings (<see cref="RainPuddles"/>). Each shape has four
/// 32x32 tables, a cell per 1/32 of the decal's width (rows down its v, columns along its u): the lowest
/// height (0-255) within 1, 2, 3 and 4 cells of each cell's middle.
/// </summary>
public static class PuddleShapes
{
	public const int Cells = 32;
	public const int RingReach = 4;

	private static readonly string[] Data =
	{
		"",
		"",
		"",
	};

	private static byte[][] _tables;

	/// <summary> A shape's tables: table k-1 (within k cells) starts at (k-1) * Cells * Cells. </summary>
	public static byte[] Tables( int shape )
	{
		_tables ??= Data.Select( Convert.FromBase64String ).ToArray();
		return _tables[Math.Clamp( shape, 0, _tables.Length - 1 )];
	}

	public static int Count => Data.Length;
}
